<x-layouts.app :heading="$release->number"><div class="toolbar"><div><span class="status {{ strtolower($release->status) }}">{{ str_replace('_',' ',$release->status) }}</span><span class="muted">{{ $release->project }} · v{{ $release->version }}</span></div>@if($release->status==='DRAFT' && auth()->user()->can('releases.update'))<a class="btn" href="{{ route('releases.edit',$release) }}">Edit draft</a>@endif</div><div class="two-col"><article class="panel"><h2>Release details</h2><dl><dt>Product</dt><dd>{{ $release->product?->name ?? 'Not linked' }}</dd><dt>Release type</dt><dd>{{ $release->release_type }}</dd><dt>Owner</dt><dd>{{ $release->creator->name }}</dd><dt>Description</dt><dd>{{ $release->description }}</dd></dl><h3>Components</h3><ul>@forelse($release->components as $component)<li>{{ $component->name }} {{ $component->version ? '· '.$component->version : '' }}</li>@empty<li class="muted">No components documented.</li>@endforelse</ul></article><article class="panel"><h2>Workflow action</h2>@php($next=['DRAFT'=>'SUBMITTED','SUBMITTED'=>'UNDER_REVIEW','UNDER_REVIEW'=>'APPROVED','REJECTED'=>'DRAFT','APPROVED'=>'RELEASED','RELEASED'=>'CLOSED'][$release->status] ?? null)@if($next)<form method="post" action="{{ route('releases.transition',$release) }}">@csrf <input type="hidden" name="status" value="{{ $next }}"><p>Move this release to <b>{{ str_replace('_',' ',$next) }}</b>.</p><label>Comment<textarea name="comments" rows="3" placeholder="Required for rejections"></textarea></label><button class="btn primary">{{ $next==='SUBMITTED' ? 'Submit release' : 'Confirm '.$next }}</button></form>@endif @if($release->status==='UNDER_REVIEW')<form method="post" action="{{ route('releases.transition',$release) }}" class="danger-form">@csrf <input type="hidden" name="status" value="REJECTED"><label>Rejection comment<textarea name="comments" rows="3" required></textarea></label><button class="btn danger">Reject release</button></form>@endif</article></div><article class="panel"><h2>Release timeline</h2><div class="timeline">@foreach($release->history as $event)<div><span class="timeline-dot"></span><b>{{ $event->action }}</b> · {{ $event->user?->name ?? 'System' }}<small>{{ $event->created_at->format('d M Y H:i') }} · {{ $event->previous_status ?? '—' }} → {{ $event->new_status }} {{ $event->comments ? '· '.$event->comments : '' }}</small></div>@endforeach</div></article></x-layouts.app>
